{
  "findings": [
    {
      "check_id": "CKV_AWS_260",
      "title": "Ingress rule allows RDP from the internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "CRITICAL",
      "explanation": "Allowing RDP access from 0.0.0.0/0 exposes the associated resource to the internet and increases the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/8\"]\n}",
  "fix_summary": "Restricted RDP access to a private IP range to reduce exposure to the internet."
}
